import sys
def _fail(t, e, tb, _d=sys.excepthook):
    if issubclass(t, AssertionError):
        print('check failed:', e); sys.exit(1)
    _d(t, e, tb)
sys.excepthook = _fail
import sys
sys.path.insert(0, '_tools')
import kbingest as k
maps, bad = k.load_patterns()
rules = [rx for m in maps if m.language == 'lua' for role, kind, rx in m.rules if role == 'def']
names = lambda line: {m.group('name') for m in (rx.search(line) for rx in rules) if m}
for line, name in (('function f(', 'f'), ('function M.f(x)', 'f'), ('  function M:f (x)', 'f'), ('function a.b.c(', 'c'), ('local function g(', 'g')):
    assert names(line) == {name}, ('the shipped Lua def rules do not name the function', line, names(line))
for line in ('local x = function(', '-- function f(', 'x = 1'):
    assert not names(line), ('a shipped Lua def rule names a function on a line that defines none', line, names(line))
